$config=require __DIR__.'/config.php'; require_once __DIR__.'/includes/database.php'; require_once __DIR__.'/includes/functions.php'; require_once __DIR__.'/includes/auth.php'; require_once __DIR__.'/includes/csrf.php'; require_once __DIR__.'/includes/email.php';
