if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$account=trim($_POST['account']??'');$password=$_POST['password']??'';if($account===''||$password==='')$error='请输入用户名/邮箱和密码';else{try{$stmt=db()->prepare('SELECT id,username,email,password,status,email_verified_at,oauth_provider FROM users WHERE username=? OR email=? LIMIT 1');$stmt->execute([$account,$account]);$u=$stmt->fetch();if(!$u)$error='用户名/邮箱或密码错误';elseif((int)$u['status']!==1)$error='你的账号已被禁用';elseif(!empty($u['oauth_provider']))$error='该账号使用阿宅账号登录，请使用阿宅账号登录';elseif(empty($u['email_verified_at']))$error='请先验证邮箱后再登录。<a href="/resend_verification.php">重新发送验证邮件</a>';elseif(empty($u['password'])||!password_verify($password,$u['password']))$error='用户名/邮箱或密码错误';else{login_user((int)$u['id'],$u['username']);if(password_needs_rehash($u['password'],PASSWORD_DEFAULT)){db()->prepare('UPDATE users SET password=?,updated_at=CURRENT_TIMESTAMP WHERE id=?')->execute([password_hash($password,PASSWORD_DEFAULT),(int)$u['id']]);}log_action((int)$u['id'],null,'login',$u['username']);redirect('/dashboard/');}}catch(Throwable $e){error_log('[AZhai Sub Login] '.$e->getMessage());$error='登录失败，请稍后重试';}}}
